  'Execute each transfer from the merchant SIM with USSD / the operator app. The Android forwarder on that SIM submits the signed confirmation SMS automatically; only then does the transfer settle. If you must type the confirmation by hand it goes to a second administrator for approval – it never settles on your word alone.':
    "Exécutez chaque transfert depuis la SIM marchande par USSD / l'application de l'opérateur. Le transmetteur Android sur cette SIM envoie automatiquement le SMS de confirmation signé ; le transfert n'est réglé qu'à ce moment. Si vous devez saisir la confirmation à la main, elle part chez un second administrateur pour approbation – rien n'est réglé sur votre seule parole.",
