  'Thanks – we will credit your wallet as soon as the payment is independently confirmed': 'Merci – nous créditerons votre portefeuille dès que le paiement sera confirmé de façon indépendante',
  'The agent checks this ID before paying out': "L'agent vérifie cette pièce d'identité avant de verser",
  'The agent enters this code to hand you the cash. Funds leave your wallet only when they confirm.':
    "L'agent saisit ce code pour vous remettre les espèces. Les fonds ne quittent votre portefeuille qu'à sa confirmation.",
  'The amount stays in your wallet but is ring-fenced: it cannot be spent until you release it.':
    'Le montant reste dans votre portefeuille mais est cantonné : il ne peut pas être dépensé tant que vous ne le libérez pas.',
  'The buyer says they paid {0}. Confirm receipt to release escrow.': "L'acheteur dit avoir payé {0}. Confirmez la réception pour libérer le séquestre.",
  'The client opens a merchant account (': 'Le client ouvre un compte marchand (',
  'The conversion into {0} is quoted once there is something to settle.': "La conversion en {0} est cotée dès qu'il y a quelque chose à régler.",
  'The customer creates a cash-out request in their app and shows you the code. Confirm it to receive the funds in your float, then hand over the cash.':
    'Le client crée une demande de retrait dans son application et vous montre le code. Confirmez-le pour recevoir les fonds dans votre fonds de caisse, puis remettez les espèces.',
  "The customer wording below is the switch's own state, never a guess: «Confirmation en cours» means do not repeat the payment.":
    "Le libellé client ci-dessous est l'état propre du switch, jamais une supposition : « Confirmation en cours » signifie ne pas répéter le paiement.",
  "The developer portal is for merchant and developer accounts, and for developers invited into a client's organisation.":
    "Le portail développeur s'adresse aux comptes marchands et développeurs, et aux développeurs invités dans l'organisation d'un client.",
  'The fee rules that apply to your account right now (merchant &gt; tier &gt; country &gt; platform). Fixed parts are in base-currency minor units.':
    "Les règles de frais qui s'appliquent à votre compte en ce moment (marchand &gt; palier &gt; pays &gt; plateforme). Les parts fixes sont en unités mineures de la devise de base.",
  'The lender receives your score, band and the factors above for the period you choose. You can revoke at any time; every read is logged.':
    'Le prêteur reçoit votre score, votre tranche et les facteurs ci-dessus pour la période que vous choisissez. Vous pouvez révoquer à tout moment ; chaque lecture est journalisée.',
  'The local payout is being executed from the payout account right now. It can no longer be recalled.':
    "Le versement local est en cours d'exécution depuis le compte de versement. Il ne peut plus être rappelé.",
  "The number you will pay from – it is matched against the operator's receipt": "Le numéro depuis lequel vous paierez – il est rapproché du reçu de l'opérateur",
  'The QR centre is for merchant accounts.': 'Le centre QR est réservé aux comptes marchands.',
  'The recipient must confirm receiving': 'Le bénéficiaire doit confirmer recevoir',
