  'Balance {{balance}}. Prefund now so payouts keep flowing.': 'Solde {{balance}}. Préfinancez maintenant pour que les versements continuent.',
  'Balance allocated': 'Solde alloué',
  'Balance enters circulation solely through confirmed external funding, administrator issuance (proposed by one admin, approved by a different admin with the issuance permission under step-up), liquidity prefunding of payout floats, or an administrator-configured programme. Users, agents, merchants and devices can never create balance; the ledger refuses any posting from the treasury without an issuance authority.':
    "Un solde n'entre en circulation que par un financement externe confirmé, une émission administrateur (proposée par un administrateur, approuvée par un autre disposant de la permission d'émission sous step-up), un préfinancement de liquidité des flottes de versement, ou un programme configuré par un administrateur. Utilisateurs, agents, marchands et dispositifs ne peuvent jamais créer de solde ; le grand livre refuse toute écriture depuis la trésorerie sans autorité d'émission.",
