  "bitcoinSettlement must be 'btc' or 'fiat'": "bitcoinSettlement doit être 'btc' ou 'fiat'",
  'BitriPay balances are a redeemable claim on the authorised issuer, backed 1:1 by cleared safeguarded funds. Issuable ≤ cleared reserves − pending redemptions − reserved exposure − e-money outstanding. No administrator can type an amount into existence.':
    "Les soldes BitriPay sont une créance remboursable sur l'émetteur agréé, couverte à 1:1 par des fonds cantonnés compensés. Émissible ≤ réserves compensées − remboursements en attente − exposition réservée − monnaie électronique en circulation. Aucun administrateur ne peut faire apparaître un montant en le saisissant.",
  'BitriPay fee': 'Frais BitriPay',
  'BitriPay for people without a smartphone or with very little data: a USSD menu on any phone, SMS keyword commands, and a tiny no-JavaScript web. Same wallets, limits and PIN checks as the app.':
    "BitriPay pour les personnes sans smartphone ou avec très peu de données : un menu USSD sur n'importe quel téléphone, des commandes SMS par mot-clé et un web minimal sans JavaScript. Mêmes portefeuilles, limites et contrôles de PIN que l'application.",
  'BitriPay initiates, orchestrates and reconciles; the switch settles. Every state here comes from an authenticated observation or a dual-approved correction.':
    "BitriPay initie, orchestre et réconcilie ; le switch règle. Chaque état ici provient d'une observation authentifiée ou d'une correction doublement approuvée.",
