  'Every administrative action, with who did it and the details': 'Chaque action administrative, avec son auteur et les détails',
  'Every agent reads through typed tools under a policy you publish here. Agents propose; people approve. Nothing here can mint, release, unfreeze or change a corridor.':
    'Chaque agent lit à travers des outils typés sous une politique que vous publiez ici. Les agents proposent ; les personnes approuvent. Rien ici ne peut émettre, libérer, dégeler ou modifier un corridor.',
  'Every any-to-any movement (card → mobile money, mobile money → bank, bank → QR…). Funding legs settle through gateways or the direct rails; payout legs to bank / mobile money appear in Approvals → Withdrawals.':
    'Chaque mouvement de tout vers tout (carte → mobile money, mobile money → banque, banque → QR…). Les segments de financement se règlent via les passerelles ou les rails directs ; les segments de versement vers banque / mobile money apparaissent sous Approbations → Retraits.',
  'Every binding starts in shadow mode: the agent reads and reports, side-effecting tools are refused. After':
    "Chaque liaison démarre en mode observation : l'agent lit et rapporte, les outils à effets sont refusés. Après",
  'Every channel': 'Tous les canaux',
  'Every charge is a ledger posting to the fees account with the tax share in its metadata, so accounting and VAT returns come straight from the ledger.':
    'Chaque prélèvement est une écriture au compte de frais avec la part de taxe dans ses métadonnées, de sorte que la comptabilité et les déclarations de TVA sortent directement du grand livre.',
  'Every chart family': 'Toutes les familles de graphiques',
  'Every event × channel × recipient with its delivery status. Contact details are masked.': 'Chaque événement × canal × destinataire avec son statut de livraison. Les coordonnées sont masquées.',
  'Every go-live item is green': 'Chaque point de mise en service est au vert',
  "Every logical route declares how it is initiated, confirmed and settled, its expected completion, refund path and whether processing is automatic, assisted (a verifier confirms evidence) or manual. External legs always depend on the payer's own bank, operator or a licensed processor.":
    "Chaque route logique déclare comment elle est initiée, confirmée et réglée, son délai attendu, son chemin de remboursement et si le traitement est automatique, assisté (un vérificateur confirme les preuves) ou manuel. Les segments externes dépendent toujours de la banque, de l'opérateur ou du processeur agréé du payeur.",
  'Every model call goes through one gateway with a margin floor; every operations agent is bound to an event, shadow-first; people confirm money.':
    "Chaque appel de modèle passe par une passerelle unique avec une marge plancher ; chaque agent d'exploitation est lié à un événement, en observation d'abord ; les personnes confirment l'argent.",
  'Every OTP, payment, payout, KYC and security message is rendered from these templates. Use': 'Chaque message OTP, paiement, versement, KYC et sécurité est rendu à partir de ces modèles. Utilisez',
  'Every statement generated for a holder is numbered, hashed and written to the audit log.': "Chaque relevé généré pour un titulaire est numéroté, haché et inscrit au journal d'audit.",
  'Every threshold has been met on the last': 'Chaque seuil a été atteint sur les derniers',
  'Every transaction balances per currency and every wallet equals the sum of its entries ({0} transactions checked).':
    'Chaque transaction est équilibrée par devise et chaque portefeuille égale la somme de ses écritures ({0} transactions vérifiées).',
