  'Live customer funds are not accepted: real card processors are refused on every corridor until the platform is switched to live in Gateway controls and each corridor records its authorised collection partner, payout partner and licence reference. Cross-border transfers are a regulated money-transfer service regardless of how payouts are executed.':
    "Les fonds réels des clients ne sont pas acceptés : les processeurs carte réels sont refusés sur chaque corridor jusqu'à ce que la plateforme passe en live dans Contrôles de passerelle et que chaque corridor enregistre son partenaire de collecte autorisé, son partenaire de versement et sa référence de licence. Les transferts transfrontaliers sont un service de transfert de fonds réglementé quelle que soit la manière dont les versements sont exécutés.",
  'Live customer funds cannot be accepted until every blocking item below is complete. The switch to live is refused by the API while any blocking item is open.':
    "Les fonds réels des clients ne peuvent pas être acceptés tant que chaque point bloquant ci-dessous n'est pas complété. Le passage en live est refusé par l'API tant qu'un point bloquant est ouvert.",
  'Live e-money may be issued only when BitriPay holds the e-money authorisation in the jurisdiction, or a licensed bank / EMI is the legal issuer and BitriPay is its distributor. Sandbox programmes have no real-world value.':
    "De la monnaie électronique réelle ne peut être émise que si BitriPay détient l'autorisation de monnaie électronique dans la juridiction, ou si une banque / un EME agréé est l'émetteur légal et BitriPay son distributeur. Les programmes sandbox n'ont aucune valeur réelle.",
