  'Maintenance window': 'Fenêtre de maintenance',
  'Maker-checker is on: the person who proposes a decision cannot approve it. Approvals require your transaction PIN or a passkey step-up. Screenshots and typed references from payers are supporting notes only.':
    "Le principe des quatre yeux est actif : la personne qui propose une décision ne peut pas l'approuver. Les approbations nécessitent votre PIN de transaction ou un step-up par clé d'accès. Les captures d'écran et références saisies par les payeurs ne sont que des notes d'appui.",
