  "The agent writes for the site's audience with the site's facts, proposes internal links and a social pack, and files the draft for review. It never invents numbers, partners or licences.":
    "L'agent écrit pour l'audience du site avec les faits du site, propose des liens internes et un kit réseaux sociaux, et dépose le brouillon pour relecture. Il n'invente jamais de chiffres, de partenaires ni de licences.",
