  'The transfer of {{amount}} to {{recipient}} failed{{reason}}. Your balance is unchanged.': 'Le transfert de {{amount}} à {{recipient}} a échoué{{reason}}. Votre solde est inchangé.',
  'The VAT rate must be between 0 and 100 percent': 'Le taux de TVA doit être compris entre 0 et 100 pour cent',
